import React, { Component } from 'react';
import moment from 'moment';
import { requestHeaderDELETEWithAuth, requestHeaderGETWithAuth } from 'src/Rest-API/Header';
import { getUserDataFromLocalStorage, logoutProcedureForLocalStorage } from 'src/Utils/AuthRelatedThings';
import { Logger, reloadPage } from '../../Utils/Utils';
import { Loading } from '../Statuses/Statuses';
import Table from 'react-bootstrap/Table';
import { CButton } from '@coreui/react';
import StatusModal from '../Modals/StatusModal';
import FailureModal from '../Modals/FailureModal';
import { BACKEND_TYPING_SPEED_SERVICE_BASE_URL } from 'src/Rest-API/EnvironmentSpecificThings';

const FILE_NAME = "TypingSourceWebsiteList.js";

const initialState = {
	isLoaded: false,
	loadingModalVisible: false,
	loadingModalState: 0,
	failureModalVisible: false,
	sourceWebsiteListData: []
};

class TypingSourceWebsiteList extends Component {

	constructor(props) {
		super(props);
		this.state = JSON.parse(JSON.stringify(initialState));
	}

	resetStateToDefault() {
		this.setState(JSON.parse(JSON.stringify(initialState)));
	}

	componentDidMount() {
		document.title = "Satanlabs - Source Websites";
		this.fetchSourceWebsiteList();
	}

	fetchSourceWebsiteList() {
		let API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + '/source/list?offset=0';
		const userData = getUserDataFromLocalStorage();

		fetch(API_URL, requestHeaderGETWithAuth(userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_1", "result", result);
				if(result.code === 1001) {
					//success
					this.setState({
						isLoaded: true,
						sourceWebsiteListData: result.data
					});
				} else {
					//something horrible happened
					this.setState({
						loadingModalVisible: false,
						loadingModalState: 0,
						failureModalVisible: true
					});
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_1", "error", error);
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
		);
	}

	reloadData() {
		this.resetStateToDefault();
		this.fetchSourceWebsiteList();
	}

	markSourceWebsiteDeleted(id) {
		if(window.confirm("Surely want to DELETE source website id = " + id + " ?")) {
			this.callDeletionApi(id);
		}
	}

	callDeletionApi(id) {
		this.setState({
			loadingModalVisible: true,
			loadingModalState: 0,
		});

		const API_URL = BACKEND_TYPING_SPEED_SERVICE_BASE_URL + "/source/" + id;
		const userData = getUserDataFromLocalStorage();
		fetch(API_URL, requestHeaderDELETEWithAuth(null, userData.authToken))
		.then(response => {
			if(response.status === 200)
				return response.json();
			if(response.status === 401) {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
				setTimeout(() => {
					logoutProcedureForLocalStorage();
					reloadPage();
				}, 500);
			} else {
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
			throw new Error("HTTP status is " + response.status);
		})
		.then(
			(result) => {
				Logger(FILE_NAME, "callApi", "FETCH_DELETE", "result", result);
				if(result.code === 1001) {
					//success
					this.setState({
						loadingModalState: 1
					});

					setTimeout(() => {
						this.setState({
							loadingModalVisible: false,
							loadingModalState: 0,
						});
						this.reloadData();
					}, 500);
				} else {
					//something horrible happened
					this.setState({
						loadingModalVisible: false,
						loadingModalState: 0,
						failureModalVisible: true
					});
				}
			},
			(error) => {
				Logger(FILE_NAME, "callApi", "FETCH_DELETE", "error", error);
				this.setState({
					loadingModalVisible: false,
					loadingModalState: 0,
					failureModalVisible: true
				});
			}
		);
	}

	render() {
		Logger(FILE_NAME, "render", "", "this.state", this.state);

		return (
			this.state.isLoaded ?
			<div>
				{/* Quick links */}
				<div style={{ display: 'flex', gap: '16px', marginBottom: '24px', flexWrap: 'wrap' }}>
					<a href="#/typing-speed/source/save" style={{ textDecoration: 'none', flex: 1, minWidth: '200px' }}>
						<div style={{
							padding: '24px',
							backgroundColor: '#d4edda',
							borderRadius: '8px',
							border: '1px solid #c3e6cb',
							textAlign: 'center',
							cursor: 'pointer',
							transition: 'transform 0.2s',
						}}>
							<h3 style={{ margin: 0, color: '#155724' }}>🌐 Add Source Website</h3>
							<p style={{ margin: '8px 0 0', color: '#155724', opacity: 0.8 }}>Register a new typing test website</p>
						</div>
					</a>
					<a href="#/typing-speed" style={{ textDecoration: 'none', flex: 1, minWidth: '200px' }}>
						<div style={{
							padding: '24px',
							backgroundColor: '#cce5ff',
							borderRadius: '8px',
							border: '1px solid #b8daff',
							textAlign: 'center',
							cursor: 'pointer',
							transition: 'transform 0.2s',
						}}>
							<h3 style={{ margin: 0, color: '#004085' }}>⌨️ Typing Sessions</h3>
							<p style={{ margin: '8px 0 0', color: '#004085', opacity: 0.8 }}>View typing session history</p>
						</div>
					</a>
				</div>

				<h2>Source Websites List :</h2>
				<CButton color="success" className="px-4" onClick={() => this.reloadData()}>reloadData</CButton>
				<br /><br />
				<Table striped bordered hover color='success' style={{'width':'100%'}}>
					<thead>
						<tr>
						<th>#</th>
						<th>Name</th>
						<th>URL</th>
						<th>createdOn</th>
						<th>Actions</th>
						</tr>
					</thead>
					<tbody>
						{
							this.state.sourceWebsiteListData.map(
								item =>
								<tr key={"source_website_item_id_" + item.id}>
									<td>{item.id}</td>
									<td>{item.name}</td>
									<td><a href={item.url} target="_blank" rel="noopener noreferrer">{item.url}</a></td>
									<td>{item.createdOn} ~ {moment(item.createdOn).format('YYYY/MM/DD HH:mm ddd')}</td>
									<td>
										<CButton color="danger" className="px-4" onClick={() => this.markSourceWebsiteDeleted(item.id)}>DELETE</CButton>
									</td>
								</tr>
							)
						}
					</tbody>
				</Table>
				<StatusModal visible={this.state.loadingModalVisible} loadingModalState={this.state.loadingModalState} />
				<FailureModal visible={this.state.failureModalVisible} />
			</div>
			 : <Loading />
		);
	}

}

export default TypingSourceWebsiteList;
